#[cfg(unix)]
enum EvalReply {
    Ok(String),
    Err(String),
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CommandOutcomeKind {
    Eval,
    Complete,
    Log,
}

#[cfg(unix)]
impl CommandOutcomeKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Eval => "eval",
            Self::Complete => "complete",
            Self::Log => "log",
        }
    }
}

