#[cfg(unix)]
fn print_controller_help() {
    println!("commands:");
    for line in controller_help_control_command_synopsis() {
        println!("  {line}");
    }
    for line in controller_help_hook_command_synopsis() {
        println!("  {line}");
    }
    for line in controller_help_runtime_command_synopsis() {
        println!("  {line}");
    }
}

#[cfg(unix)]
fn print_reply_payload(command: &str, payload: &str) {
    if payload.trim().is_empty() {
        return;
    }
    if command.starts_with("jseval ") || command == "jsinit" {
        print_eval_payload(payload);
        return;
    }
    if payload.contains('\n') {
        println!("{payload}");
    } else {
        println!("{payload}");
    }
}

#[cfg(unix)]
fn print_command_outcome(outcome: &CommandOutcome) {
    match outcome.kind {
        CommandOutcomeKind::Complete => {
            if outcome.items.is_empty() {
                println!("(no completions)");
            } else {
                for item in &outcome.items {
                    println!("{item}");
                }
            }
        }
        CommandOutcomeKind::Log => {
            if let Some(payload) = outcome.payload.as_deref() {
                println!("{payload}");
            }
        }
        CommandOutcomeKind::Eval => {
            if outcome.ok {
                if let Some(payload) = outcome.payload.as_deref() {
                    print_reply_payload(&outcome.command, payload);
                }
            } else if let Some(error) = outcome.error.as_deref() {
                println!("[error] {error}");
            }
        }
    }
}

#[cfg(unix)]
fn parse_payload_json(payload: &str) -> Option<Value> {
    let trimmed = payload.trim();
    if trimmed.is_empty() {
        return None;
    }
    serde_json::from_str(trimmed).ok()
}

#[cfg(unix)]
fn render_command_outcome_json(outcome: &CommandOutcome) -> Value {
    let payload_json = outcome.payload.as_deref().and_then(parse_payload_json);
    json!({
        "ok": outcome.ok,
        "command": outcome.command,
        "kind": outcome.kind.as_str(),
        "payload": outcome.payload,
        "payloadJson": payload_json,
        "items": outcome.items,
        "error": outcome.error,
        "logs": outcome.logs,
    })
}

#[cfg(unix)]
fn hook_capability_label(capability: HookCommandCapability) -> &'static str {
    match capability {
        HookCommandCapability::Query => "query",
        HookCommandCapability::HookInstall => "hook-install",
        HookCommandCapability::HookStatus => "hook-status",
        HookCommandCapability::HookStop => "hook-stop",
    }
}

#[cfg(unix)]
fn command_arm64e_safety_to_json(
    command: &str,
    preflight: &InjectionTargetPreflightReport,
    trace: Option<&InjectionTrace>,
) -> Value {
    let arm64e_summary = arm64e_runtime_summary_to_json(preflight, trace);
    let hook_capability = command_required_capability(command)
        .ok()
        .flatten()
        .map(hook_capability_label);
    let requires_inline_hooks = command_requests_inline_hook_install(command).ok();
    let is_pac_command = command.trim().starts_with("pac.");
    let target_uses_arm64e = preflight.target_uses_arm64e;
    let preferred_thread_bootstrap_resolved = arm64e_summary["preferredThreadBootstrapResolved"]
        .as_bool()
        .unwrap_or(false);
    let override_required_for_fallback = arm64e_summary["overrideRequiredForFallback"]
        .as_bool()
        .unwrap_or(false);

    let (classification, risk_level, recommended_action, recommended_action_phase) = match target_uses_arm64e {
        Some(true) if requires_inline_hooks == Some(true) && override_required_for_fallback => (
            "blocked-without-override",
            "high",
            "query-only-until-override",
            "query",
        ),
        Some(true) if requires_inline_hooks == Some(true) && preferred_thread_bootstrap_resolved => {
            ("inline-risky", "elevated", "run-with-caution", "hook-install")
        }
        Some(true) if requires_inline_hooks == Some(true) => ("inline-risky", "elevated", "preflight-more", "preflight"),
        Some(true) if is_pac_command => ("safe-readonly-pac", "low", "run", "query"),
        Some(true) => ("safe-readonly", "low", "run", "query"),
        Some(false) if requires_inline_hooks == Some(true) => ("standard-inline", "normal", "run", "hook-install"),
        Some(false) => ("standard-readonly", "low", "run", "query"),
        None => ("unknown", "unknown", "preflight-more", "preflight"),
    };

    json!({
        "classification": classification,
        "riskLevel": risk_level,
        "recommendedAction": recommended_action,
        "recommendedActionClass": arm64e_recommended_action_class(recommended_action),
        "recommendedActionPhase": recommended_action_phase,
        "targetUsesArm64e": target_uses_arm64e,
        "requiresInlineHooks": requires_inline_hooks,
        "hookCapability": hook_capability,
        "pacCommand": is_pac_command,
        "preferredThreadBootstrapResolved": preferred_thread_bootstrap_resolved,
        "overrideRequiredForFallback": override_required_for_fallback,
    })
}

#[cfg(unix)]
fn command_error_recovery_to_json(
    command: &str,
    err: &Error,
    preflight: &InjectionTargetPreflightReport,
    trace: Option<&InjectionTrace>,
) -> Value {
    let arm64e_safety = command_arm64e_safety_to_json(command, preflight, trace);
    let override_required_for_fallback = arm64e_safety["overrideRequiredForFallback"]
        .as_bool()
        .unwrap_or(false);
    let requires_inline_hooks = arm64e_safety["requiresInlineHooks"].as_bool().unwrap_or(false);
    let hook_blocked = matches!(err, Error::State(message) if message.contains("hook-effective-blocked"));

    if override_required_for_fallback && requires_inline_hooks {
        let commands = arm64e_readonly_recovery_commands();
        let command_json_templates = commands
            .iter()
            .map(|template| command_json_template_entry(template))
            .collect::<Vec<_>>();

        return json!({
            "strategy": "arm64e-query-only-until-override",
            "reason": "arm64e fallback bootstrap requires explicit override before inline-hook commands should be retried",
            "arm64eConstrained": true,
            "readonlyOnly": true,
            "appliesToHookInstall": true,
            "hookBlocked": hook_blocked,
            "overrideRequiredForFallback": true,
            "overrideEnv": "IOS_RUSTFRIDA_ALLOW_ARM64E_PTHREAD_FALLBACK",
            "nextActionKey": "hook.query",
            "nextActionPhase": "query",
            "nextStepPhase": "query",
            "recommendedAction": "run-readonly-diagnostics",
            "recommendedActionClass": "readonly-diagnostics",
            "recommendedActionKey": "hook.query",
            "recommendedActionPhase": "query",
            "commandCount": commands.len(),
            "commands": commands,
            "firstCommand": commands.first().cloned(),
            "commandJsonTemplateCount": command_json_templates.len(),
            "commandJsonTemplates": command_json_templates,
        });
    }

    Value::Null
}

#[cfg(unix)]
fn hook_failure_recovery_to_json(
    hook_action_key: Option<&str>,
    preflight: &InjectionTargetPreflightReport,
    trace: Option<&InjectionTrace>,
) -> Value {
    let arm64e_summary = arm64e_runtime_summary_to_json(preflight, trace);
    let override_required_for_fallback = arm64e_summary["overrideRequiredForFallback"]
        .as_bool()
        .unwrap_or(false);

    if override_required_for_fallback && hook_action_key == Some("hook.install") {
        let commands = arm64e_readonly_recovery_commands();
        let command_json_templates = commands
            .iter()
            .map(|template| command_json_template_entry(template))
            .collect::<Vec<_>>();

        return json!({
            "strategy": "arm64e-query-only-until-override",
            "reason": "arm64e fallback bootstrap requires explicit override before inline-hook recovery should be retried",
            "arm64eConstrained": true,
            "readonlyOnly": true,
            "appliesToHookInstall": true,
            "overrideRequiredForFallback": true,
            "overrideEnv": "IOS_RUSTFRIDA_ALLOW_ARM64E_PTHREAD_FALLBACK",
            "nextActionKey": "hook.query",
            "nextActionPhase": "query",
            "nextStepPhase": "query",
            "recommendedAction": "run-readonly-diagnostics",
            "recommendedActionClass": "readonly-diagnostics",
            "recommendedActionKey": "hook.query",
            "recommendedActionPhase": "query",
            "commandCount": commands.len(),
            "commands": commands,
            "firstCommand": commands.first().cloned(),
            "commandJsonTemplateCount": command_json_templates.len(),
            "commandJsonTemplates": command_json_templates,
        });
    }

    Value::Null
}

#[cfg(unix)]
#[cfg_attr(not(test), allow(dead_code))]
fn render_command_error_json(command: &str, err: &Error, logs: &[String]) -> Value {
    let diagnostics = match err {
        Error::State(message) if message.contains("hook-effective-blocked") => {
            let parsed = parse_hook_effective_blocked_details(message);
            json!({
                "phase": "hook-policy",
                "actionKey": normalize_hook_action_key(parsed.action_key),
                "commandGroup": normalize_hook_command_group(parsed.command_group),
                "blockedBy": normalize_hook_blocked_by(parsed.blocked_by),
                "commandMode": normalize_hook_command_mode(parsed.command_mode),
                "baseCommandMode": normalize_hook_command_mode(parsed.base_command_mode),
                "effectiveCommandMode": normalize_hook_command_mode(parsed.effective_command_mode),
                "autoDowngradedToQueryOnly": parse_bool_token(parsed.auto_downgraded_to_query_only),
                "autoDowngradeReason": normalize_hook_auto_downgrade_reason(parsed.auto_downgrade_reason),
                "recommendation": parsed.recommendation,
                "coexistenceMode": normalize_hook_coexistence_mode(parsed.coexistence_mode),
                "backendPressure": normalize_hook_backend_pressure(parsed.backend_pressure),
                "coexistenceLayerRequired": parse_bool_token(parsed.coexistence_layer_required),
                "coexistenceLayerStatus": parsed.coexistence_layer_status,
                "coexistenceLayerPreferredPhase": normalize_hook_fallback_phase(parsed.coexistence_layer_preferred_phase),
                "coexistenceLayerRecommendedActionKey": normalize_hook_action_key(parsed.coexistence_layer_recommended_action_key),
                "coexistenceLayerSummary": parsed.coexistence_layer_summary,
                "fallbackActionKey": normalize_hook_action_key(parsed.fallback_action_key),
                "fallbackStepId": normalize_hook_fallback_step_id(parsed.fallback_step_id),
                "fallbackCommand": parsed.fallback_command,
                "fallbackPhase": normalize_hook_fallback_phase(parsed.fallback_phase),
            })
        }
        _ => Value::Null,
    };
    json!({
        "ok": false,
        "command": command,
        "errorKind": match err {
            Error::Io(_) => "io",
            Error::Protocol(_) => "protocol",
            Error::InvalidArgument(_) => "invalid-argument",
            Error::State(_) => "state",
            Error::Unsupported(_) => "unsupported",
        },
        "error": err.to_string(),
        "diagnostics": diagnostics,
        "logs": logs,
    })
}

#[cfg(unix)]
fn render_command_outcome_json_with_context(
    outcome: &CommandOutcome,
    context: &CommandJsonContext<'_>,
) -> Value {
    let recovery_summary = hook_arm64e_recovery_summary_to_json(context.preflight, context.trace);
    let mut rendered = render_command_outcome_json(outcome)
        .as_object()
        .cloned()
        .unwrap_or_default();
    rendered.insert(
        "arm64eSummary".into(),
        arm64e_runtime_summary_to_json(context.preflight, context.trace),
    );
    rendered.insert(
        "arm64eCommandSafety".into(),
        command_arm64e_safety_to_json(&outcome.command, context.preflight, context.trace),
    );
    rendered.insert("hookRecoverySummary".into(), recovery_summary.clone());
    rendered.insert("recoverySummary".into(), recovery_summary.clone());
    rendered.insert("arm64eRecoverySummary".into(), recovery_summary);
    Value::Object(rendered)
}

#[cfg(unix)]
fn render_command_error_json_with_context(
    command: &str,
    err: &Error,
    logs: &[String],
    context: &CommandJsonContext<'_>,
) -> Value {
    let mut rendered = render_injection_result_json(
        context.config,
        context.pid,
        context.socket_path,
        context.plan,
        context.injection_environment,
        context.doctor,
        context.preflight,
        context.trace,
        context.hello,
        context.ping,
        context.hook_environment_notice,
        context.hook_environment_checked,
        context.jsinit_result,
        context.loadjs_result,
        logs,
        Some(err),
    )
    .as_object()
    .cloned()
    .unwrap_or_default();

    rendered.insert("command".into(), json!(command));
    rendered.insert(
        "arm64eCommandSafety".into(),
        command_arm64e_safety_to_json(command, context.preflight, context.trace),
    );
    rendered.insert(
        "recovery".into(),
        command_error_recovery_to_json(command, err, context.preflight, context.trace),
    );
    rendered.insert("kind".into(), Value::Null);
    rendered.insert("payload".into(), Value::Null);
    rendered.insert("payloadJson".into(), Value::Null);
    rendered.insert("items".into(), Value::Array(Vec::new()));
    rendered.insert("logs".into(), json!(logs));

    Value::Object(rendered)
}

#[cfg(unix)]
fn print_eval_payload(payload: &str) {
    if payload.trim().is_empty() {
        return;
    }
    if payload.contains('\n') {
        println!("{payload}");
    } else {
        println!("=> {payload}");
    }
}

#[cfg(unix)]
fn read_agent_event(stream: &mut UnixStream, context: &str) -> Result<AgentEvent> {
    match read_frame(stream) {
        Ok((kind, payload)) => decode_event(kind, payload),
        Err(Error::Io(err)) if matches!(err.kind(), ErrorKind::TimedOut | ErrorKind::WouldBlock) => {
            Err(Error::State(format!("{context} timed out")))
        }
        Err(err) => Err(err),
    }
}

#[cfg(unix)]
fn event_name(event: &AgentEvent) -> &'static str {
    match event {
        AgentEvent::Hello(_) => "HELLO",
        AgentEvent::Log(_) => "LOG",
        AgentEvent::Complete(_) => "COMPLETE",
        AgentEvent::EvalOk(_) => "EVAL_OK",
        AgentEvent::EvalErr(_) => "EVAL_ERR",
    }
}

