    fn materialize_help_template(template: &str) -> String {
        let mut command = template
            .split(" #")
            .next()
            .map(str::trim)
            .unwrap_or_default()
            .to_string();

        let placeholders = [
            ("<filter>", "UIView"),
            ("<class>", "UIViewController"),
            ("<module>", "DemoBinary"),
            ("<symbol>", "malloc"),
            ("<offset>", "0x1234"),
            ("<query>", "malloc"),
            ("<script>", "console.log(1)"),
            ("<expr>", "1 + 1"),
            ("<prefix>", "objc."),
            ("<path-or-name>", "libSystem.B.dylib"),
            ("<path>", "@loader_path"),
            ("<name|cmd|index>", "LC_UUID"),
            ("<segment>", "__TEXT"),
            ("<section>", "__text"),
            ("<address>", "0x1234"),
            ("<protocol>", "NSObject"),
            ("<selector>", "viewDidLoad"),
            ("<property>", "view"),
            ("<ivar>", "_viewControllerFlags"),
            ("<name>", "UIView"),
            ("<object>", "0x1234"),
            ("<mangled-symbol>", "_$s5Demo14ViewControllerC11viewDidLoadyyF"),
            ("<type>", "ViewController"),
            ("<method>", "viewDidLoad"),
            ("<member>", "viewDidLoad"),
            ("<kind>", "metadata-accessor"),
            ("<type|protocol>", "ViewController"),
            ("<objc-filter|native-target>", "UIViewController"),
        ];
        for (placeholder, value) in placeholders {
            command = command.replace(placeholder, value);
        }

        let optional_tokens = [
            ("[meta]", "meta"),
            ("[filter]", "UIView"),
            ("[module]", "DemoBinary"),
            ("[-- template]", "-- fd"),
            ("[query]", "UIView"),
            ("[required]", "optional"),
            ("[instance]", "class"),
        ];
        for (placeholder, value) in optional_tokens {
            command = command.replace(placeholder, value);
        }

        command.split_whitespace().collect::<Vec<_>>().join(" ")
    }

    fn materialized_help_commands(
        synopsis_lines: &[&str],
        skip_alias_summary: bool,
    ) -> (HashSet<String>, Vec<String>) {
        let mut commands = HashSet::new();
        let mut duplicates = Vec::new();
        for synopsis in synopsis_lines {
            if skip_alias_summary && synopsis.contains("...") {
                continue;
            }
            for variant in split_help_synopsis_variants(synopsis) {
                let variant = materialize_help_template(variant);
                if variant.is_empty() {
                    continue;
                }
                if !commands.insert(variant.clone()) {
                    duplicates.push(variant);
                }
            }
        }
        (commands, duplicates)
    }

    fn materialized_runtime_help_commands() -> HashSet<String> {
        let (commands, _duplicates) =
            materialized_help_commands(controller_help_runtime_command_synopsis(), true);
        commands
    }

    fn materialized_hook_action_templates() -> Vec<String> {
        let mut templates = HashSet::<String>::new();
        let action_keys = ["hook.query", "hook.bootstrap", "hook.install", "hook.status", "hook.stop"];
        let preferred_paths = [
            "inline-safe",
            "inline-cautious",
            "inline-risky",
            "query-only",
            "arm64e-query-only",
            "cleanup-only",
            "blocked",
        ];

        for action_key in action_keys {
            for preferred_path in preferred_paths {
                for template in hook_action_command_templates(action_key, preferred_path) {
                    templates.insert(template);
                }
            }
        }

        let mut sorted = templates.into_iter().collect::<Vec<_>>();
        sorted.sort_unstable();
        sorted
    }

    fn command_shape(command: &str) -> (String, bool) {
        (
            command.split_whitespace().next().unwrap_or_default().to_string(),
            command.contains(" -- "),
        )
    }

    fn assert_command_json_template_kind_count_pairs(value: &Value, path: &str) {
        match value {
            Value::Object(map) => {
                if map.contains_key("commandJsonTemplateCount") {
                    assert!(
                        map.contains_key("commandJsonInstructionTemplateCount"),
                        "missing commandJsonInstructionTemplateCount at {path}"
                    );
                    assert!(
                        map.contains_key("commandJsonExecutableTemplateCount"),
                        "missing commandJsonExecutableTemplateCount at {path}"
                    );
                }
                for key in map.keys() {
                    if key == "commandJsonTemplateCount" {
                        continue;
                    }
                    if let Some(prefix) = key.strip_suffix("CommandJsonTemplateCount") {
                        let instruction_key = format!("{prefix}CommandJsonInstructionTemplateCount");
                        let executable_key = format!("{prefix}CommandJsonExecutableTemplateCount");
                        assert!(
                            map.contains_key(&instruction_key),
                            "missing {instruction_key} at {path}"
                        );
                        assert!(
                            map.contains_key(&executable_key),
                            "missing {executable_key} at {path}"
                        );
                    }
                }
                for (key, child) in map {
                    let child_path = if path.is_empty() {
                        key.to_string()
                    } else {
                        format!("{path}.{key}")
                    };
                    assert_command_json_template_kind_count_pairs(child, &child_path);
                }
            }
            Value::Array(items) => {
                for (index, child) in items.iter().enumerate() {
                    let child_path = format!("{path}[{index}]");
                    assert_command_json_template_kind_count_pairs(child, &child_path);
                }
            }
            _ => {}
        }
    }

