    #[test]
    fn controller_help_synopsis_has_no_duplicate_materialized_commands() {
        let (_control_commands, control_duplicates) =
            materialized_help_commands(controller_help_control_command_synopsis(), false);
        assert!(
            control_duplicates.is_empty(),
            "control help has duplicate commands: {:?}",
            control_duplicates
        );

        let (_hook_commands, hook_duplicates) =
            materialized_help_commands(controller_help_hook_command_synopsis(), false);
        assert!(
            hook_duplicates.is_empty(),
            "hook help has duplicate commands: {:?}",
            hook_duplicates
        );

        let (_runtime_commands, runtime_duplicates) =
            materialized_help_commands(controller_help_runtime_command_synopsis(), true);
        assert!(
            runtime_duplicates.is_empty(),
            "runtime help has duplicate commands: {:?}",
            runtime_duplicates
        );
    }

    #[test]
    fn controller_help_synopsis_categories_stay_disjoint() {
        let (control_commands, _control_duplicates) =
            materialized_help_commands(controller_help_control_command_synopsis(), false);
        let (hook_commands, _hook_duplicates) =
            materialized_help_commands(controller_help_hook_command_synopsis(), false);
        let (runtime_commands, _runtime_duplicates) =
            materialized_help_commands(controller_help_runtime_command_synopsis(), true);

        let control_hook = control_commands
            .intersection(&hook_commands)
            .cloned()
            .collect::<Vec<_>>();
        let control_runtime = control_commands
            .intersection(&runtime_commands)
            .cloned()
            .collect::<Vec<_>>();
        let hook_runtime = hook_commands
            .intersection(&runtime_commands)
            .cloned()
            .collect::<Vec<_>>();

        assert!(
            control_hook.is_empty(),
            "control/hook help commands should be disjoint, overlap: {:?}",
            control_hook
        );
        assert!(
            control_runtime.is_empty(),
            "control/runtime help commands should be disjoint, overlap: {:?}",
            control_runtime
        );
        assert!(
            hook_runtime.is_empty(),
            "hook/runtime help commands should be disjoint, overlap: {:?}",
            hook_runtime
        );
    }

    #[test]
    fn controller_help_hook_synopsis_routes_to_hook_capabilities() {
        for synopsis in controller_help_hook_command_synopsis() {
            for variant in split_help_synopsis_variants(synopsis) {
                let command = materialize_help_template(variant);
                assert!(!command.is_empty(), "hook help command should not be empty");

                let capability = command_required_capability(&command)
                    .expect("hook command capability")
                    .expect("hook command should always map to a capability");
                assert!(
                    matches!(
                        capability,
                        HookCommandCapability::HookInstall
                            | HookCommandCapability::HookStatus
                            | HookCommandCapability::HookStop
                    ),
                    "hook help command should map to hook capability: {command}"
                );

                let installs = command_requests_inline_hook_install(&command)
                    .expect("hook install intent should parse");
                if installs {
                    assert_eq!(
                        capability,
                        HookCommandCapability::HookInstall,
                        "install commands must map to install capability: {command}"
                    );
                } else if command.contains(" status") {
                    assert_eq!(
                        capability,
                        HookCommandCapability::HookStatus,
                        "status commands must map to status capability: {command}"
                    );
                } else if command.contains(" stop") {
                    assert_eq!(
                        capability,
                        HookCommandCapability::HookStop,
                        "stop commands must map to stop capability: {command}"
                    );
                } else {
                    assert_eq!(
                        capability,
                        HookCommandCapability::HookInstall,
                        "non-status/non-stop hook commands should be install paths: {command}"
                    );
                }
            }
        }
    }

    #[test]
    fn controller_help_control_synopsis_stays_non_hook() {
        for synopsis in controller_help_control_command_synopsis() {
            for variant in split_help_synopsis_variants(synopsis) {
                let command = materialize_help_template(variant);
                assert!(!command.is_empty(), "control help command should not be empty");
                assert!(
                    !command_requires_inline_hooks(&command),
                    "control command should not require inline hooks: {command}"
                );
                assert!(
                    !command_requests_inline_hook_install(&command).expect("control install check"),
                    "control command should not request inline install: {command}"
                );

                let capability = command_required_capability(&command).expect("control capability");
                match command.as_str() {
                    "exit" => assert_eq!(
                        capability,
                        None,
                        "exit should bypass hook capability routing"
                    ),
                    _ if command.starts_with("jscomplete ") => assert_eq!(
                        capability,
                        None,
                        "jscomplete should bypass hook capability routing"
                    ),
                    _ => assert_eq!(
                        capability,
                        Some(HookCommandCapability::Query),
                        "control command should remain query capability: {command}"
                    ),
                }
            }
        }
    }

    #[test]
    fn query_only_suggested_sequence_stays_query_capability() {
        for preferred_path in ["query-only", "arm64e-query-only"] {
            let commands = hook_automation_suggested_sequence(preferred_path);
            assert!(!commands.is_empty(), "query-only suggested sequence should not be empty");

            for command in commands {
                assert_eq!(
                    command_required_capability(&command).expect("suggested sequence capability"),
                    Some(HookCommandCapability::Query),
                    "query-only suggested sequence should remain query capability: {command}"
                );
                assert!(
                    !command_requires_inline_hooks(&command),
                    "query-only suggested sequence should avoid inline-hook commands: {command}"
                );
            }
        }
    }

