    #[test]
    fn hook_automation_prefers_query_pac_path_when_arm64e_override_is_required() {
        let report = HookEnvironmentReport {
            active_backend: None,
            backends: vec![],
            warnings: vec![],
        };
        let backend_matrix = hook_backend_matrix_to_json(&report, &report);
        let strategy = HookStrategyDecision {
            policy: HookPolicy::Warn,
            strategy: "internal-inline-safe".into(),
            allowed: true,
            inline_hooks_allowed: true,
            reason: None,
        };
        let actions = hook_effective_actions(
            &hook_environment_recommended_actions(&report, Some(&strategy)),
            &hook_environment_recommended_actions(&report, Some(&strategy)),
        );
        let coexistence = super::hook_coexistence_to_json_with_arm64e(
            &actions,
            &backend_matrix,
            HookAutomationArm64eContext {
                query_only_until_override: true,
            },
        );
        let automation = hook_automation_to_json_with_arm64e(
            &actions,
            &backend_matrix,
            HookAutomationArm64eContext {
                query_only_until_override: true,
            },
        );
        assert_command_json_template_kind_count_pairs(&coexistence, "coexistence");
        assert_command_json_template_kind_count_pairs(&automation, "automation");
        assert_eq!(
            coexistence["backendAdaptation"],
            automation["backendAdaptation"],
            "arm64e-query-only.backendAdaptationParity"
        );
        for key in [
            "backendAdaptationMode",
            "backendAdaptationAlignment",
            "backendAdaptationBias",
            "backendAdaptationSummary",
            "nextActionKey",
            "nextActionCommandGroup",
            "nextActionAllowed",
            "nextActionBlockedBy",
            "nextActionBranch",
            "nextActionReadyToRun",
            "nextStepActionKey",
            "nextStepCommandGroup",
            "nextStepAllowed",
            "nextStepBlockedBy",
            "nextStepBranch",
            "nextStepCommand",
            "nextStepPhase",
            "nextStepCommandJsonEligible",
            "nextStepReadyToRun",
            "nextStepRequiresFallback",
        ] {
            assert_eq!(coexistence[key], automation[key], "arm64e-query-only.{key}");
        }
        assert_eq!(coexistence["nextStepChainSource"], "next-action");
        assert_eq!(automation["nextStepChainSource"], "next-action");
        assert_eq!(automation["hasFallbackPlan"], false);
        assert!(automation["fallbackPlan"].is_null());

        assert_eq!(coexistence["preferredPath"], "arm64e-query-only");
        assert_eq!(automation["preferredPath"], "arm64e-query-only");
        assert_eq!(automation["arm64eConstrainedQueryOnly"], true);
        assert_eq!(
            automation["arm64eOverrideEnv"],
            "IOS_RUSTFRIDA_ALLOW_ARM64E_PTHREAD_FALLBACK"
        );
        assert_eq!(automation["nextActionKey"], "hook.query");
        assert_eq!(automation["suggestedSequence"][0], "native.hookenv");
        assert_eq!(automation["suggestedSequence"][1], "pac.available");
        assert_eq!(automation["suggestedSequence"][2], "pac.arm64e");
        assert_eq!(automation["backendAdaptation"]["recommendedActionBias"], "query");
        assert_eq!(
            automation["backendAdaptation"]["summary"],
            "arm64e fallback bootstrap is active; stay on query/PAC diagnostics until explicit override is enabled"
        );

        let templates = automation["commandTemplates"].as_array().expect("command templates");
        let bootstrap_templates = templates
            .iter()
            .find(|item| item["actionKey"] == "hook.bootstrap")
            .expect("hook.bootstrap templates");
        assert_eq!(bootstrap_templates["templateCount"], 2);
        assert_eq!(
            bootstrap_templates["templates"][1],
            "controller --preflight-only --preflight-json --pid <pid>"
        );
        assert!(
            bootstrap_templates["templates"]
                .as_array()
                .expect("bootstrap template array")
                .iter()
                .all(|item| item.as_str().unwrap_or_default() != "controller --inject-json --pid <pid>")
        );

        let install_templates = templates
            .iter()
            .find(|item| item["actionKey"] == "hook.install")
            .expect("hook.install templates");
        assert_eq!(install_templates["templateCount"], 0);
        assert_eq!(install_templates["templates"], json!([]));
    }

    #[test]
    fn hook_automation_fallback_escalation_prefers_arm64e_query_only_path_when_override_is_required() {
        let report = HookEnvironmentReport {
            active_backend: None,
            backends: vec![],
            warnings: vec![],
        };
        let backend_matrix = hook_backend_matrix_to_json(&report, &report);
        let actions = vec![
            HookEffectiveAction {
                action_key: "hook.bootstrap",
                command_group: "bootstrap",
                allowed: false,
                blocked_by: "both",
                priority: 2,
                controller_allowed: false,
                target_allowed: false,
                controller_priority: 2,
                target_priority: 2,
                recommendation: "bootstrap blocked".into(),
                controller_reason: Some("controller blocked bootstrap".into()),
                target_reason: Some("target blocked bootstrap".into()),
            },
            HookEffectiveAction {
                action_key: "hook.install",
                command_group: "hook-install",
                allowed: false,
                blocked_by: "both",
                priority: 3,
                controller_allowed: false,
                target_allowed: false,
                controller_priority: 3,
                target_priority: 3,
                recommendation: "install blocked".into(),
                controller_reason: Some("controller blocked install".into()),
                target_reason: Some("target blocked install".into()),
            },
            HookEffectiveAction {
                action_key: "hook.status",
                command_group: "hook-status",
                allowed: false,
                blocked_by: "both",
                priority: 4,
                controller_allowed: false,
                target_allowed: false,
                controller_priority: 4,
                target_priority: 4,
                recommendation: "status blocked".into(),
                controller_reason: Some("controller blocked status".into()),
                target_reason: Some("target blocked status".into()),
            },
            HookEffectiveAction {
                action_key: "hook.stop",
                command_group: "hook-stop",
                allowed: false,
                blocked_by: "both",
                priority: 5,
                controller_allowed: false,
                target_allowed: false,
                controller_priority: 5,
                target_priority: 5,
                recommendation: "stop blocked".into(),
                controller_reason: Some("controller blocked stop".into()),
                target_reason: Some("target blocked stop".into()),
            },
        ];

        let coexistence = super::hook_coexistence_to_json_with_arm64e(
            &actions,
            &backend_matrix,
            HookAutomationArm64eContext {
                query_only_until_override: true,
            },
        );
        let automation = hook_automation_to_json_with_arm64e(
            &actions,
            &backend_matrix,
            HookAutomationArm64eContext {
                query_only_until_override: true,
            },
        );
        assert_command_json_template_kind_count_pairs(&coexistence, "coexistence");
        assert_command_json_template_kind_count_pairs(&automation, "automation");
        assert_eq!(
            coexistence["backendAdaptation"],
            automation["backendAdaptation"],
            "arm64e-fallback.backendAdaptationParity"
        );
        for key in [
            "backendAdaptationMode",
            "backendAdaptationAlignment",
            "backendAdaptationBias",
            "backendAdaptationSummary",
            "nextStepRequiresFallback",
        ] {
            assert_eq!(coexistence[key], automation[key], "arm64e-fallback.{key}");
        }
        assert_ne!(
            coexistence["nextActionKey"],
            automation["nextActionKey"],
            "arm64e-fallback.nextActionKey should diverge between views"
        );
        assert_ne!(
            coexistence["nextStepCommand"],
            automation["nextStepCommand"],
            "arm64e-fallback.nextStepCommand should diverge between views"
        );
        assert_eq!(coexistence["nextStepChainSource"], "next-action");
        assert_eq!(automation["nextStepChainSource"], "fallback-plan");
        assert_eq!(coexistence["preferredPath"], "arm64e-query-only");

        assert_eq!(automation["preferredPath"], "arm64e-query-only");
        assert_eq!(automation["hasFallbackPlan"], true);
        assert_eq!(
            automation["fallbackPlan"]["suggestedEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(automation["fallbackPlan"]["suggestedActionPhase"], "query");
        assert_eq!(
            automation["fallbackPlan"]["suggestedActionClass"],
            "readonly-diagnostics"
        );
        assert_eq!(
            automation["fallbackPlan"]["escalationRecommendations"][0]["key"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["escalationRecommendations"][0]["phase"],
            "query"
        );
        assert_eq!(
            automation["fallbackPlan"]["escalationRecommendations"][0]["overrideEnv"],
            "IOS_RUSTFRIDA_ALLOW_ARM64E_PTHREAD_FALLBACK"
        );
        assert_eq!(
            automation["fallbackPlan"]["escalationRecommendations"][0]["templates"][1],
            "pac.available"
        );
        assert_eq!(
            automation["fallbackPlan"]["errorCodeRouting"]["hook-fallback-hook-install-failed"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["defaultRecommendedEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["defaultEffectiveEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["ready"]["resolveDefaultEffectiveEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["ready"]["queryOnlyEffectiveEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["ready"]["queryOnlyWouldUsePath"],
            true
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["ready"]["queryOnlyResolveResultEffectiveEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["ready"]["phaseResolveExampleQueryOnlyEffectiveEscalationKey"],
            "arm64e-query-only-path"
        );
        assert_eq!(
            automation["fallbackPlan"]["routingDecision"]["ready"]["phaseResolveExampleQueryOnlyResultEffectiveEscalationKey"],
            "arm64e-query-only-path"
        );
    }

    #[test]
    fn render_injection_result_json_classifies_task_for_pid_failure_without_trace() {
        let config = ControllerConfig {
            mode: InjectionMode::Attach,
            pid: Some(42),
            bundle_id: None,
            spawn_command: None,
            command: None,
            command_json: false,
            list_images_json: false,
            preflight_only: false,
            preflight_json: false,
            inject_json: true,
            agent_path: LEGACY_AGENT_PATH_ROOTFUL.into(),
            entry_symbol: "ios_agent_entry".into(),
            script_path: None,
            socket_path: None,
            connect_timeout_secs: 15,
        };

        let environment = InjectionEnvironmentReport {
            dry_run: false,
            bootstrap_wait_ms: Some(1000),
            hook_policy: HookPolicy::Warn,
            hook_strategy: HookStrategyDecision {
                policy: HookPolicy::Warn,
                strategy: "internal-inline".into(),
                allowed: true,
                inline_hooks_allowed: true,
                reason: None,
            },
            hook_environment: HookEnvironmentReport {
                active_backend: None,
                backends: vec![],
                warnings: vec![],
            },
        };
        let plan = MachInjector
            .plan(&InjectionTarget {
                pid: 42,
                dylib_path: DEFAULT_AGENT_PATH.into(),
                entry_symbol: "ios_agent_entry".into(),
                socket_path: "/tmp/iosrf.sock".into(),
            })
            .expect("plan");
        let preflight = InjectionTargetPreflightReport {
            main_image: None,
            target_images: vec![],
            target_image_count: 0,
            target_uses_arm64e: Some(false),
            thread_bootstrap_kind: ThreadBootstrapKind::PthreadCreateFromMachThread,
            thread_bootstrap_label: "pthread_create_from_mach_thread".into(),
            thread_bootstrap_address: 0,
            thread_bootstrap_raw_address: 0,
            thread_bootstrap_canonicalized: false,
            target_hook_environment: HookEnvironmentReport {
                active_backend: None,
                backends: vec![],
                warnings: vec![],
            },
            target_hook_strategy: HookStrategyDecision {
                policy: HookPolicy::Warn,
                strategy: "internal-inline".into(),
                allowed: true,
                inline_hooks_allowed: true,
                reason: None,
            },
            resolved_loader_symbols: vec![],
        };

        let doctor = analyze_doctor_report(&config, 42, Path::new("/tmp/iosrf.sock"), &environment, &preflight);
        let rendered = render_injection_result_json(
            &config,
            42,
            "/tmp/iosrf.sock",
            &plan,
            &environment,
            &doctor,
            &preflight,
            None,
            None,
            None,
            None,
            false,
            None,
            None,
            &[],
            Some(&Error::State(
                "task_for_pid failed: (os/kern) failure (0x5); verify jailbreak/root context, task_for_pid entitlement/exception, and that the target process is not protected by platform restrictions".into(),
            )),
        );

        assert_eq!(rendered["ok"], false);
        assert!(rendered["trace"].is_null());
        assert_eq!(rendered["diagnostics"]["phase"], "mach");
        assert_eq!(rendered["diagnostics"]["code"], "task-for-pid");
        assert!(rendered["diagnostics"]["hook"].is_null());
        assert_eq!(rendered["diagnostics"]["handshakeStage"], "awaiting-hello");
        assert_eq!(rendered["diagnostics"]["failedStep"], "hello");
        assert!(rendered["diagnostics"]["hints"]
            .as_array()
            .expect("hints array")
            .iter()
            .any(|item| item.as_str().unwrap_or_default().contains(LEGACY_AGENT_PATH_ROOTFUL)));
        assert!(rendered["handshake"]["errors"]["hello"].is_null());
        assert_eq!(rendered["handshake"]["steps"]["hello"], "pending");
        assert_eq!(rendered["handshake"]["steps"]["ping"], "pending");
        assert_eq!(rendered["handshake"]["steps"]["hookEnvironment"], "pending");
    }

